avail = [1, 0, 1]
alloc = {'P1': [2, 1, 0], 'P2': [1, 1, 0], 'P3': [2, 0, 1], 'P4': [0, 1, 2]}
need  = {'P1': [0, 1, 0], 'P2': [0, 0, 1], 'P3': [1, 1, 0], 'P4': [2, 1, 0]}

done = set()
order = []
while len(done) < len(need):
    for p in need:
        if p in done:
            continue
        if all(need[p][i] <= avail[i] for i in range(3)):
            for i in range(3):
                avail[i] += alloc[p][i]
            done.add(p)
            order.append(p)
            break
    else:
        break
print(order, avail)
